WITH filtered AS (SELECT id, session_id, page, event_time, LENGTH(event_type) AS event_type_length, CEIL(duration_sec) AS duration_sec_whole FROM web_events WHERE event_time >= '2023-05-01'), flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM filtered), islands AS (SELECT id, page, event_time, duration_sec_whole, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT burst_id, PERCENTILE_APPROX(burst_id, 0.5) AS burst_id_p50, COUNT(*) FILTER (WHERE page = '/checkout') AS checkout_rows, PERCENTILE_APPROX(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles FROM islands GROUP BY burst_id HAVING checkout_rows > 1
